record OrderPlaced(OrderId id, BigDecimal total) { }

// publisher: any bean holding the injected publisher
publisher.publishEvent(new OrderPlaced(id, total));

// subscriber: no reference to the publisher, discovered by the container
@Component
class Billing {
    @EventListener
    void on(OrderPlaced e) { /* ... */ }
}

var bus = new SubmissionPublisher<OrderPlaced>(ForkJoinPool.commonPool(), 256);

bus.subscribe(new Flow.Subscriber<OrderPlaced>() {
    public void onSubscribe(Flow.Subscription s) { s.request(Long.MAX_VALUE); }
    public void onNext(OrderPlaced e) { billing.handle(e); }
    public void onError(Throwable t) { log.error("bus", t); }
    public void onComplete() { }
});

bus.submit(new OrderPlaced(id, total));   // offer() variants drop instead of blocking
